import pytest

from cadmate import check, footprint, generate, ipc, server

# Pads and courtyards of KiCad's own library footprints (kicad-footprints, Package_SO.pretty and
# Package_DFN_QFN.pretty), generated by KiCad from the same JEDEC / datasheet values used below.
SOIC8 = {
    "pins": 8, "pitch": 1.27, "body_width": "3.9+/-0.1", "body_length": [4.8, 5.0], "overall_width": "6+/-0.2",
    "lead_width": [0.31, 0.51], "lead_length": [0.4, 1.27], "height": 1.75, "standoff": 0.1,
}
TSSOP14 = {
    "pins": 14, "pitch": 0.65, "body_width": "4.4+/-0.1", "body_length": "5+/-0.1", "overall_width": 6.4,
    "lead_width": [0.17, 0.30], "lead_length": "0.6+/-0.15", "package": "TSSOP",
}
QFN16 = {
    "pins": 16, "pitch": 0.5, "body_width": [2.9, 3.0, 3.1], "body_length": [2.9, 3.0, 3.1], "lead_width": [0.18, 0.3],
    "lead_length": [0.3, 0.5], "ep_width": 1.7, "ep_length": 1.7, "heel_reduction": 0.05,
}


def build(family, params, **kw):
    r = generate.generate(family, params, **kw)
    assert r["ok"], r
    return r, footprint.parse(r["text"])


def pads(fp):
    return [(p.number, round(p.x, 4), round(p.y, 4), round(p.width, 4), round(p.height, 4)) for p in fp.pads]


def test_dimension_formats():
    assert ipc.dim(1.27) == ipc.Dim(1.27, 1.27, 1.27)
    assert ipc.dim([0.4, 1.27]).nom == pytest.approx(0.835)
    assert ipc.dim("6.0+/-0.2").min == pytest.approx(5.8)
    assert ipc.dim("6.0 ± 0.2").max == pytest.approx(6.2)
    assert ipc.dim("0.31..0.41..0.51").nom == pytest.approx(0.41)
    assert ipc.dim({"min": 2.9, "max": 3.1}).nom == pytest.approx(3.0)
    with pytest.raises(ValueError):
        ipc.dim([3.1, 2.9])
    with pytest.raises(ValueError):
        ipc.dim("about 3")


def test_soic8_matches_kicad_library():
    r, fp = build("soic", SOIC8)
    assert r["name"] == "SOIC-8_3.9x4.9mm_P1.27mm"
    ys = [-1.905, -0.635, 0.635, 1.905]
    expected = [(str(i + 1), -2.475, y, 1.95, 0.6) for i, y in enumerate(ys)]
    expected += [(str(i + 5), 2.475, y, 1.95, 0.6) for i, y in enumerate(reversed(ys))]
    assert pads(fp) == expected
    assert vars(fp.courtyard) == {"xmin": -3.7, "ymin": -2.7, "xmax": 3.7, "ymax": 2.7}


def test_tssop14_matches_kicad_library():
    r, fp = build("soic", TSSOP14)
    assert r["name"] == "TSSOP-14_4.4x5mm_P0.65mm"
    assert {(p.width, p.height) for p in fp.pads} == {(1.475, 0.4)}
    assert fp.pads[0].x == pytest.approx(-2.8625) and fp.pads[0].y == pytest.approx(-1.95)
    assert vars(fp.courtyard) == {"xmin": -3.85, "ymin": -2.75, "xmax": 3.85, "ymax": 2.75}


def test_qfn16_matches_kicad_library():
    r, fp = build("qfn", QFN16)
    assert r["name"] == "QFN-16-1EP_3x3mm_P0.5mm_EP1.7x1.7mm"
    numbered = pads(fp)[:17]
    assert numbered[0] == ("1", -1.4625, -0.75, 0.825, 0.25)
    assert numbered[4] == ("5", -0.75, 1.4625, 0.25, 0.825)
    assert numbered[8] == ("9", 1.4625, 0.75, 0.825, 0.25)
    assert numbered[12] == ("13", 0.75, -1.4625, 0.25, 0.825)
    assert numbered[16] == ("17", 0.0, 0.0, 1.7, 1.7)
    paste = [p for p in fp.pads if p.number == ""]
    assert sorted((p.x, p.y, p.width) for p in paste) == [(-0.425, -0.425, 0.69), (-0.425, 0.425, 0.69), (0.425, -0.425, 0.69), (0.425, 0.425, 0.69)]
    assert fp.pads[16].layers == ["F.Cu", "F.Mask"]
    assert vars(fp.courtyard) == {"xmin": -2.13, "ymin": -2.13, "xmax": 2.13, "ymax": 2.13}


@pytest.mark.parametrize("family,params", [("soic", SOIC8), ("soic", TSSOP14), ("qfn", QFN16)])
def test_generated_footprints_pass_review_cleanly(family, params):
    r, fp = build(family, params)
    assert r["warnings"] == []
    review = check.check_footprint(fp)
    assert review["ok"] and review["warnings"] == [], review
    assert review["measured"]["F.SilkS_to_pad"] >= 0.2 - 1e-6


def test_wider_tolerances_give_longer_pads():
    _, nominal = build("soic", TSSOP14 | {"overall_width": "6.4+/-0.2"})
    _, most = build("soic", TSSOP14 | {"overall_width": "6.4+/-0.2"}, density="most")
    assert most.pads[0].width > nominal.pads[0].width > 1.475


def test_dfn_and_exposed_pad_clearance():
    params = {"pins_x": 0, "pins_y": 4, "pitch": 0.5, "body_width": 2, "body_length": 2, "lead_width": [0.2, 0.3],
              "lead_length": [0.25, 0.45], "ep_width": 1.2, "ep_length": 1.6}
    r, fp = build("qfn", params)
    assert r["name"] == "DFN-8-1EP_2x2mm_P0.5mm_EP1.2x1.6mm"
    assert any("shortened" in w for w in r["warnings"])
    ep = next(p for p in fp.pads if p.number == "9")
    inner = min(abs(p.x) - p.width / 2 for p in fp.pads if p.number in list("12345678"))
    assert inner - ep.width / 2 >= generate.EP_PAD_CLEARANCE - 1e-9


def test_bad_input_is_refused():
    assert generate.generate("soic", {"pins": 8})["errors"][0].startswith("missing")
    r = generate.generate("soic", SOIC8 | {"pins": 7})
    assert not r["ok"] and any("even" in e for e in r["errors"])
    r = generate.generate("soic", SOIC8 | {"lead_length": 1.5})  # whole lead instead of the foot
    assert not r["ok"] and any("foot" in e for e in r["errors"])
    r = generate.generate("qfn", QFN16 | {"pins": 18})
    assert not r["ok"]


def test_custom_through_hole_header_uses_pin1_origin():
    params = {"body_width": 2.54, "body_length": 10.16,
              "pad_rows": [{"first": 1, "count": 4, "x": 10, "y": 20, "dy": 2.54, "width": 1.7, "height": 1.7, "drill": 1.0}]}
    r, fp = build("custom", params, name="Header_1x04", courtyard_clearance=0.5)
    assert not fp.smd
    assert (fp.pin1.x, fp.pin1.y, fp.pin1.shape) == (0, 0, "rect")
    assert [p.shape for p in fp.pads[1:]] == ["circle"] * 3
    assert fp.pads[3].y == pytest.approx(7.62)
    assert fp.pads[0].layers == ["*.Cu", "*.Mask"]
    assert r["warnings"] == []


def test_custom_smd_land_pattern_is_centred():
    params = {"body_width": 6, "body_length": 4, "pads": [
        {"number": 1, "x": 1, "y": 1, "width": 1.2, "height": 0.8},
        {"number": 2, "x": 1, "y": 3, "width": 1.2, "height": 0.8},
        {"number": 3, "x": 6, "y": 2, "width": 2, "height": 3},
    ]}
    r, fp = build("custom", params, name="Odd")
    assert fp.smd and r["report"]["origin"] == "center"
    assert fp.pad_extents.center == pytest.approx((0, 0))


def test_review_catches_broken_footprints():
    _, fp = build("soic", SOIC8)
    fp.pads[1].y = fp.pads[0].y + 0.3  # pads 1 and 2 now overlap
    fp.pads[4].x = 6.0  # pad 5 outside the courtyard
    r = check.check_footprint(fp)
    assert any("overlap" in e for e in r["errors"])
    assert any("outside the courtyard" in e for e in r["errors"])


def test_review_catches_silk_on_pads_and_close_pads():
    text = generate.generate("soic", SOIC8)["text"]
    text = text.replace("(layer \"F.SilkS\"))", "(layer \"F.SilkS\"))\n\t(fp_line (start -3 -1.9) (end -2 -1.9) (stroke (width 0.12) (type solid)) (layer \"F.SilkS\"))", 1)
    r = check.check_footprint(footprint.parse(text))
    assert any("silkscreen lies on pad 1" in e for e in r["errors"])
    r = generate.generate("soic", SOIC8 | {"lead_width": [1.1, 1.15]})  # pads wider than the pitch allows
    assert not r["ok"] and r["text"] is None and any("overlap" in e for e in r["errors"])


def test_compare_reports_differences():
    _, a = build("soic", SOIC8)
    _, b = build("soic", SOIC8, density="most")
    c = check.compare_footprints(a, b)
    assert not c["same_pads"] and c["max_pad_difference"] > 0.1
    assert check.compare_footprints(a, a)["same_pads"]


def test_server_writes_into_a_pretty_folder(tmp_path):
    lib = tmp_path / "mine.pretty"
    r = server.generate_footprint("soic", SOIC8, str(lib))
    assert r["ok"] and (lib / "SOIC-8_3.9x4.9mm_P1.27mm.kicad_mod").exists()
    again = server.generate_footprint("soic", SOIC8, str(lib))
    assert not again["ok"] and "exists" in again["errors"][0]
    assert server.generate_footprint("soic", SOIC8, str(lib), overwrite=True)["ok"]
    assert (lib / "SOIC-8_3.9x4.9mm_P1.27mm.kicad_mod.bak").exists()
    assert not server.generate_footprint("soic", SOIC8, str(tmp_path / "plain"))["ok"]
    review = server.check_footprint(r["written"], "soic", SOIC8)
    assert review["ok"] and review["vs_datasheet"]["same_pads"]


def test_ipc7251_hole_and_pad_from_lead():
    # Worked example published with the IPC-7251 / IPC-2222 rules: 0.55 mm lead.
    for density, hole, pad in (("most", 0.8, 1.5), ("nominal", 0.75, 1.35), ("least", 0.7, 1.2)):
        h = ipc.tht_hole(density, lead_diameter=ipc.dim(0.55))
        assert (h.drill, h.pad_w, h.pad_h, h.drill_y) == (hole, pad, pad, None)
    # Square 0.64 mm header pin: the round hole has to clear the diagonal.
    h = ipc.tht_hole("nominal", lead_width=ipc.dim(0.64), lead_thickness=ipc.dim(0.64))
    assert h.drill == 1.15 and h.drill > 0.64 * 2**0.5
    with pytest.raises(ValueError):
        ipc.tht_hole("nominal", lead_diameter=ipc.dim(0.6), slot=True)


def test_slot_for_a_flat_tab():
    h = ipc.tht_hole("nominal", lead_width=ipc.dim([1.9, 2.0]), lead_thickness=ipc.dim(0.5), slot=True)
    assert (h.drill, h.drill_y, h.pad_w, h.pad_h) == (2.2, 0.7, 2.8, 1.3)


JACK = {"body_width": 9, "body_length": 14, "pads": [
    {"number": 1, "x": 0, "y": 0, "lead_width": 2.0, "lead_thickness": 0.5, "slot": True},
    {"number": 2, "x": 0, "y": 6, "lead_width": 2.0, "lead_thickness": 0.5, "slot": True},
    {"number": 3, "x": 4.7, "y": 3, "lead_width": 2.0, "lead_thickness": 0.5, "slot": True, "rotation": 90},
    {"number": "MP", "kind": "np_thru_hole", "x": 0, "y": 10, "drill": 1.6},
]}


def test_custom_through_hole_from_lead_sizes_round_trips():
    r, fp = build("custom", JACK, name="Jack", courtyard_clearance=0.5)
    assert r["warnings"] == [], r
    p1, p3 = fp.pads[0], fp.pads[2]
    assert (p1.drill, p1.drill_y, p1.width, p1.height, p1.shape) == (2.2, 0.7, 2.8, 1.3, "roundrect")
    assert "(drill oval 2.2 0.7)" in r["text"]
    assert p3.rotation == 90 and p3.box.height == pytest.approx(2.8)
    assert fp.pads[3].kind == "np_thru_hole" and fp.pads[3].number == "" and fp.pads[3].width == 1.6
    assert r["report"]["ipc7251_holes"][0]["pads"] == ["1", "2", "3"]
    review = check.check_footprint(fp, courtyard_clearance=0.5)
    assert review["ok"] and review["warnings"] == [] and review["measured"]["min_annular_ring"] == pytest.approx(0.3)


def test_terminal_from_round_leads_at_each_density():
    row = {"first": 1, "count": 2, "x": 0, "y": 0, "dx": 5.08, "lead_diameter": [1.0, 1.1]}
    _, nominal = build("custom", {"body_width": 10, "body_length": 8, "pad_rows": [row]})
    _, most = build("custom", {"body_width": 10, "body_length": 8, "pad_rows": [row]}, density="most")
    assert (nominal.pads[0].drill, nominal.pads[0].width) == (1.3, 1.9)
    assert most.pads[0].drill > nominal.pads[0].drill and most.pads[0].shape == "rect"


def test_review_flags_thin_rings_and_compare_sees_drills():
    params = {"body_width": 3, "body_length": 3, "pads": [{"number": 1, "x": 0, "y": 0, "width": 1.2, "height": 1.2, "drill": 1.0}]}
    r, fp = build("custom", params)
    assert any("copper ring 0.100" in w for w in r["warnings"])
    _, other = build("custom", JACK, name="Jack", courtyard_clearance=0.5)
    _, same = build("custom", JACK | {"pads": [dict(p) for p in JACK["pads"]]}, name="Jack", courtyard_clearance=0.5)
    moved = JACK | {"pads": [JACK["pads"][0] | {"lead_thickness": 0.8}] + JACK["pads"][1:]}
    _, changed = build("custom", moved, name="Jack", courtyard_clearance=0.5)
    assert check.compare_footprints(other, same)["same_pads"]
    diff = check.compare_footprints(changed, other)["pad_differences"]
    assert diff[0]["pad"] == "1" and "drill" in diff[0]
